import { PF2E_FEATS } from "../data/pf2e-feats.mjs";
import { writeFile } from "node:fs/promises";
const motifs = new Set("strike unarmed heavyStrike doubleStrike charge ranged firearm bombThrow alchemicalShot fearStrike feintStrike bindStrike tripStrike dread shove trip".split(" "));
let preservedIds;
try { preservedIds=Object.keys((await import('../data/feat-description-review.mjs')).FEAT_DESCRIPTION_REVIEWS); }
catch(error) { if(error.code!=='ERR_MODULE_NOT_FOUND')throw error; }
export const MARTIAL_REVIEW_FEATS = preservedIds ? preservedIds.map(id=>PF2E_FEATS.find(feat=>feat.id===id)) : PF2E_FEATS.filter(feat=>motifs.has(feat.motif));
if(MARTIAL_REVIEW_FEATS.some(feat=>!feat))throw Error('Reviewed feat ID missing from pinned source catalog.');

/** Descriptors concern visible storytelling only. Contact count is visual, never MAP, damage dice, or actions spent. */
const profile = (motif, approach, count, distribution, weapon, tempo, shape, finish = [], subject = "targets", theme, constraints = []) => ({
  motif, ...(theme ? {theme} : {}), subject,
  design: {approach, contacts: {count, distribution, conditional: false}, weapon, tempo, shape, finish, constraints},
});
const manual = {};
const add = (names, descriptor) => names.split('|').forEach(name=>manual[name] = descriptor);
const zero = (names, motif, approach, shape, finish = [], subject = "source", theme) => add(names, profile(motif,approach,0,'none','none','settled',shape,finish,subject,theme));
const single = (names, approach, weapon, shape, finish = [], motif = 'strike', tempo = 'measured', theme) => add(names,profile(motif,approach,1,'same-target',weapon,tempo,shape,finish,'targets',theme));
const paired = (names, approach, weapon, shape, finish = [], distribution = 'same-target', tempo = 'sequential') => add(names,profile('doubleStrike',approach,2,distribution,weapon,tempo,shape,finish));

