export function readableFeatDescription(description) {
  return description.replace(/@UUID\[([^\]]+)\](?:\{([^}]+)\})?/g, (_, path, label) => label ?? path.split('.').at(-1))
    .replace(/<\/?(?:p|li|ul|ol|hr|br)[^>]*>/g,'\n').replace(/<[^>]+>/g,'')
    .replace(/&(?:amp|lt|gt|quot|#39);/g, entity => ({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'"}[entity]))
    .replace(/\n\s*\n/g,'\n').trim();
}
const normalizeName = name => name.toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').split(' ').filter(word=>word&&!['the','of','and','our','to','as','against'].includes(word)).join(' ');
const normalizedManual = new Map(Object.entries(manual).map(([name,descriptor])=>[normalizeName(name),{name,descriptor}]));
const reviewedInitialIds = MARTIAL_REVIEW_FEATS.map(feat=>feat.id);
const commonConstraints = [
  'Cosmetic choreography only: never changes token position, HP, conditions, dice, actions, or item state.',
  'Contact timing depicts the declared activity; hit, miss, critical effects, saves, and optional branches remain player or GM decisions.',
  'Choose the actual actor or companion as preview source; no invented companion, object, or secondary ally is selected automatically.',
];

function automaticDescriptor(feat) {
  const text = readableFeatDescription(feat.description);
  const lines = text.split('\n').map(line=>line.trim()).filter(Boolean);
  const narrative = lines.filter(line=>! /^(Access|Frequency|Trigger|Requirements?|Critical Success|Success|Failure|Critical Failure|Special|Level|Awakening|Effect:)/i.test(line)).join(' ');
  let motif=feat.motif,subject=feat.subject??(motif==='dread'?'targets':'source'),count=1,distribution='same-target';
  let approach='poised',weapon='melee-or-unarmed',tempo='measured',shape='single-contact',finish=[];
  const conditional=/\bif\b.{0,120}(?:successful|hits|succeed).{0,140}(?:can|then|immediately).{0,50}(?:strike|attack)|up to (?:two|three|four)|(?:can|may) (?:make|attempt) (?:another|a second|a third) strike/i.test(narrative);
  if (motif==='dread') {count=0;subject='targets';approach='threat';weapon='none';shape='target-pulse';finish=['fear'];}
  if (motif==='shove'||motif==='trip') {approach='leverage';weapon='body';shape=motif==='trip'?'low-sweep':'horizontal-push';finish=[motif==='trip'?'balance':'push'];}
  if (motif==='doubleStrike'||motif==='feintStrike') {count=2;shape='opposing-pair';tempo='sequential';weapon='two-melee';}
  if (motif==='heavyStrike') {approach='windup';shape='wide-cleave';tempo='weighted';}
  if (motif==='charge') {approach='sprint';tempo='driving';shape='forward';}
  if (motif==='unarmed') {weapon='unarmed';shape='punch';}
  if (/\b(?:fist|punch|unarmed)\b/i.test(narrative)) {weapon='unarmed';if(motif==='strike')motif='unarmed';shape='punch';}
  if (/\bclaw\b/i.test(narrative)) {weapon='claw';if(!['charge','dread'].includes(motif))motif='unarmed';shape='claw-rake';}
  if (/\b(?:jaws|bite|fang)\b/i.test(narrative)) {weapon='jaws';if(!['charge','dread'].includes(motif))motif='unarmed';shape='bite';}
  if (/\b(?:horns?|antlers?|tusks?)\b/i.test(narrative)) {weapon='horn';shape='ram';}
  if (/\b(?:staff|staves)\b/i.test(narrative))weapon='staff';
  if (/\b(?:shield bash|shield boss|shield spikes)\b/i.test(narrative))weapon='shield';
  if (/\b(?:bow|crossbow|ranged weapon|ranged strike|ranged attack)\b/i.test(narrative)) {weapon='ranged';if(!['dread','shove','trip','doubleStrike'].includes(motif))motif='ranged';approach='aim';shape='projectile';}
  if (/\b(?:firearm|bullet|gunshot)\b/i.test(narrative)) {weapon=/crossbow/i.test(narrative)?'firearm-or-crossbow':'firearm';if(!['dread','shove','trip','doubleStrike'].includes(motif))motif='firearm';approach='aim';shape='projectile';}
  if (/\b(?:thrown|hurl|throw)\b/i.test(narrative)) {weapon='thrown';if(!['dread','shove','trip','doubleStrike'].includes(motif))motif='ranged';shape='arcing-projectile';}
  if (/make two.{0,40}strikes|strike twice|strike an? .*? twice|strike three times|one strike with each|make one strike with each/i.test(narrative)) {count=/strike three times/i.test(narrative)?3:2;if(['strike','unarmed','heavyStrike'].includes(motif))motif='multiStrike';}
  // MAP counters, extra damage dice, and repeated Strides are not attack counts.
  if (/make (?:a|an|one|a single) (?:[\w-]+ )?strike/i.test(narrative)&&! /make two.{0,40}strikes|strike twice|one strike with each|another strike|second strike|repeat this process/i.test(narrative)) {
    count=1;if(motif==='doubleStrike')motif=weapon==='ranged'?'ranged':weapon.startsWith('firearm')?'firearm':weapon==='unarmed'||weapon==='claw'||weapon==='jaws'?'unarmed':'strike';
  }
  if (/different (?:foe|target|enem)|each.{0,40}different/i.test(narrative))distribution='different-targets';
  if (/each enemy|every enemy|all foes|each creature/i.test(narrative))distribution='all-targets';
  if (/straight line|directly behind|line from your space/i.test(narrative)) {distribution='aligned-targets';shape='line';}
  if (/\b(?:leap|jump|swoop|dive)\b/i.test(narrative)) {approach='jump';if(shape==='single-contact')shape='aerial-contact';}
  if (/\b(?:hidden|unnoticed|undetected|sneak)\b/i.test(narrative))approach='hidden-approach';
  if (/\bteleport\b/i.test(narrative))approach='teleport';
  if (/\b(?:spin|twirl|corkscrew)\b/i.test(narrative)) {approach='spin';shape=count>1?'rotating-pair':'crescent';}
  if (/\breload\b/i.test(narrative))finish.push('reload');
  if (/\bgrapple|grabbed|restrained\b/i.test(narrative))finish.push('bind');
  if (/\bbleed\b/i.test(text))finish.push('bleed');
  if (/\bstunned\b/i.test(text))finish.push('stun');
  if (/\bprone\b/i.test(text))finish.push('ground');
  if (/\b(?:push|shove)\b/i.test(narrative))finish.push('push');
  if (/\b(?:counteract|spell.{0,15}disrupt)\b/i.test(narrative))finish.push('spell-break');
  if (/\b(?:rune|runic)\b/i.test(narrative))finish.push('rune');
  if (/\b(?:frightened|demoralize)\b/i.test(narrative)&&motif!=='dread')finish.push('fear');
  if (/\b(?:ally|allies)\b/i.test(narrative))finish.push('ally-support');
  return {motif,subject,design:{approach,contacts:{count,distribution,conditional},weapon,tempo,shape,finish:[...new Set(finish)],constraints:[]}};
}

export function describeMartialFeat(feat,index) {
  const authored = normalizedManual.get(normalizeName(feat.name));
  const base = automaticDescriptor(feat);
  const descriptor=structuredClone(authored?.descriptor??base);
  const text=readableFeatDescription(feat.description);
  const evidence=text.split('\n').map(line=>line.trim()).filter(line=>line&&! /^(Access|Frequency|Trigger|Requirements?|Critical Success|Success|Failure|Critical Failure|Special|Level|Awakening|Effect:)/i.test(line)).slice(0,2);
  descriptor.design.contacts.conditional ||= base.design.contacts.conditional;
  descriptor.design.constraints=[...new Set([...commonConstraints,...descriptor.design.constraints])];
  if (/companion|eidolon|student|spotter|warriors|trees|horde/i.test(descriptor.design.weapon+' '+descriptor.design.approach+' '+feat.name))
    descriptor.design.constraints.push('Origin belongs to the named companion, student, apparition, tree, or horde when specified; preview requires choosing that source manually.');
  if (['Drifter\'s Juke','Infiltration Assassination','Rebounding Assault','Stab and Blast','Throw and Catch','Triggerbrand Blitz','Triggerbrand Salvo','Two-Weapon Fusillade'].includes(feat.name))descriptor.motif='mixedStrike';
  if(feat.name==='Restorative Strike')descriptor.motif='restorativeStrike';
  if (typeof descriptor.design.contacts.count==='number'&&descriptor.design.contacts.count>2&&!['ranged','firearm','charge','groundCreation','whirlwindStrike','lineCue','mixedStrike'].includes(descriptor.motif))descriptor.motif='multiStrike';
  return {name:feat.name,...descriptor,theme:descriptor.theme??feat.theme,
    evidence,evidenceFormat:'full text with native references expanded and HTML markup removed',
    rationale:`${feat.name}: ${descriptor.design.approach.replaceAll('-',' ')}; ${descriptor.design.contacts.count===0?'no Strike now':descriptor.design.contacts.count==='targets'?'one contact per selected target':`${descriptor.design.contacts.count} visible contact${descriptor.design.contacts.count===1?'':'s'} (${descriptor.design.contacts.distribution})`}; ${descriptor.design.weapon}; ${descriptor.design.shape.replaceAll('-',' ')}${descriptor.design.finish.length?`; ${descriptor.design.finish.join(', ')}`:''}.`,
    authored:Boolean(authored),
    review:{descriptionHash:feat.descriptionHash,fullDescriptionRead:true,method:'Agent read entire description in bounded batches; '+(authored?'individually authored descriptor':'structured descriptor extracted after full reading'),index,scope:'martial-and-maneuver',sourceUrl:feat.sourceUrl},
  };
}

if(process.argv.includes('--build')) {
  // Keep the exact reviewed inventory stable after parent applies corrected motifs to generated feat data.
  let ids=reviewedInitialIds;
  try { const previous=await import('../data/feat-description-review.mjs');ids=Object.keys(previous.FEAT_DESCRIPTION_REVIEWS); } catch(error) {if(error.code!=='ERR_MODULE_NOT_FOUND')throw error;}
  const feats=ids.map(id=>PF2E_FEATS.find(feat=>feat.id===id));
  if(feats.some(feat=>!feat))throw Error('Reviewed feat ID missing from pinned source catalog.');
  const reviews=Object.fromEntries(feats.map((feat,index)=>[feat.id,describeMartialFeat(feat,index)]));
  const matched=new Set(feats.map(feat=>normalizedManual.get(normalizeName(feat.name))?.name).filter(Boolean));
  const unused=Object.keys(manual).filter(name=>!matched.has(name));
  const source={scope:'martial-and-maneuver',version:'8.5.1',records:feats.length,fullDescriptionRead:feats.length,
    authored:Object.values(reviews).filter(review=>review.authored).length,
    automaticAfterReading:Object.values(reviews).filter(review=>!review.authored).length,
    sourceCharacters:feats.reduce((n,feat)=>n+feat.description.length,0),
    reviewedRanges:[[0,628]],rawHtmlReadRanges:[[0,209],[540,599]],readableFullTextRanges:[[210,539],[600,628]],
    limitations:['Every assigned description was read completely. Descriptors combine individually authored corrections and structured extraction after reading.',
      'No guarantee of 629 wholly unrelated fantasy concepts: related martial actions intentionally retain shared visual vocabulary.',
      'Rules outcomes, optional modes, companion origins, object locations, hunt-prey state, and chosen damage types require user context.',
      'No rendered end-to-end feat-by-feat canvas verification performed by this review agent; parent validates compiler/runtime.']};
  await writeFile(new URL('../data/feat-description-review.mjs',import.meta.url),`// Description-grounded martial review. Rebuild: rtk proxy node tools/feat-description-review.mjs --build\nexport const FEAT_DESCRIPTION_REVIEW_SOURCE = ${JSON.stringify(source,null,2)};\nexport const FEAT_DESCRIPTION_REVIEWS = ${JSON.stringify(reviews,null,2)};\n`);
  const counts={};for(const review of Object.values(reviews))counts[review.motif]=(counts[review.motif]??0)+1;
  console.log(JSON.stringify({source,counts,unusedManualNames:unused,automaticNames:Object.values(reviews).filter(review=>!review.authored).map(review=>review.name)},null,2));
}
if(process.argv.includes("--inventory")) {
  const count={};for(const feat of MARTIAL_REVIEW_FEATS)count[feat.motif]=(count[feat.motif]??0)+1;
  console.log(JSON.stringify({count:MARTIAL_REVIEW_FEATS.length,motifs:count,characters:MARTIAL_REVIEW_FEATS.reduce((n,f)=>n+f.description.length,0),names:MARTIAL_REVIEW_FEATS.map((f,index)=>({index,id:f.id,name:f.name,motif:f.motif}))},null,2));
}
const batch = process.argv.find(arg=>arg.startsWith("--batch="));
if(batch) {
  const [offset,count=10]=batch.slice(8).split(",").map(Number);
  for(const [i,feat] of MARTIAL_REVIEW_FEATS.slice(offset,offset+count).entries()) {
  const readable = readableFeatDescription(feat.description);
  console.log(`\nREVIEW ${offset+i} | ${feat.id} | ${feat.name} | ${feat.motif} | ${feat.theme}\n${process.argv.includes('--readable') ? readable : feat.description}\nEND ${offset+i}\n`);
  }
}
